            // 前一个相等下标尚不在当前路径，先选后一个会重复；固定同值下标递增使用。
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) {
                continue;
            }

            used[i] = true;
            path.add(nums[i]);

            backtrack(nums, used, path, answer);

            path.remove(path.size() - 1);
            used[i] = false;
        }
    }
}

